  assert.equal(isValidIsbn13("978-0-306-40615-7"), true);
});

test("ISBN-10 to ISBN-13", () => {
  assert.equal(toIsbn13("0306406152"), "9780306406157");
});

test("ISBN-13 to ISBN-10", () => {
  assert.equal(toIsbn10("9780306406157"), "0306406152");
});

test("ISBN-13 to ISBN-10 keeps hyphens and spaces out of the result", () => {
  assert.equal(toIsbn10("978-0-306-40615-7"), "0306406152");
});

