});

test("ISBN-13 to ISBN-10 rejects a bad ISBN-13", () => {
  assert.throws(() => toIsbn10("9780306406158"), /not a valid ISBN-13/);
});

test("ISBN-13 to ISBN-10 rejects a 979 prefix", () => {
  assert.throws(() => toIsbn10("9790000000001"), /not convertible to ISBN-10/);
});

