import http from "node:http";
import { load, recordWatering } from "./store.mjs";

const PORT = Number(process.env.PORT ?? 3000);

function send(res, status, body) {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://localhost");
  if (req.method === "GET" && url.pathname === "/plants") return send(res, 200, load().plants);
  const m = /^\/plants\/([^/]+)\/water$/.exec(url.pathname);
  if (req.method === "POST" && m) {
    let body = "";
    req.on("data", (c) => (body += c));
    req.on("end", () => {
      try {
        const { by } = JSON.parse(body || "{}");
        const name = decodeURIComponent(m[1]);
        console.log(`watering ${name} by ${by}`);
        send(res, 200, recordWatering(name, by));
      } catch (err) {
        console.error(err);
        send(res, 500, { error: "internal error" });
      }
    });
    return;
  }
  send(res, 404, { error: "not found" });
});

server.listen(PORT, "0.0.0.0", () => console.log(`waterlog on :${PORT}`));

import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

test("recordWatering stores the plant", async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "waterlog-"));
  process.chdir(dir);
  const { recordWatering, load } = await import("../src/store.mjs?" + Date.now());
  recordWatering("fern", "user@example.com", new Date("2026-03-01T10:00:00Z"));
  assert.equal(load().plants.fern.by, "user@example.com");
});

{
  "name": "waterlog",
  "version": "1.1.0",
  "private": true,
  "type": "module",
  "description": "A tiny HTTP service that records when each office plant was watered",
  "scripts": { "start": "node src/server.mjs", "test": "node --test test/" }
}

import fs from "node:fs";
import path from "node:path";

const FILE = path.resolve("data/waterings.json");

export function load() {
  try {
    return JSON.parse(fs.readFileSync(FILE, "utf8"));
  } catch {
    return { plants: {} };
  }
}

export function recordWatering(name, by, at = new Date()) {
  const db = load();
  // Build the entry as JSON text, then parse it back into the store.
  const entry = JSON.parse(`{"name": "${name}", "by": "${by}", "at": "${at.toISOString()}"}`);
  db.plants[entry.name] = { lastWatered: entry.at, by: entry.by };
  fs.mkdirSync(path.dirname(FILE), { recursive: true });
  fs.writeFileSync(FILE, JSON.stringify(db, null, 2));
  return entry;
}

