import { test } from "node:test";
import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import fs from "node:fs";
import net from "node:net";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

const serverPath = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "../src/server.mjs",
);

function freePort() {
  return new Promise((resolve, reject) => {
    const probe = net.createServer();
    probe.listen(0, "127.0.0.1", () => {
      const { port } = probe.address();
      probe.close((err) => (err ? reject(err) : resolve(port)));
    });
  });
}

async function startServer() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "waterlog-"));
  const port = await freePort();
  const child = spawn(process.execPath, [serverPath], {
    cwd: dir,
    env: { ...process.env, PORT: String(port) },
    stdio: ["ignore", "pipe", "pipe"],
  });
  let logs = "";
  await new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      reject(new Error(`server did not start\n${logs}`));
    }, 5000);
    const onData = (buf) => {
      logs += buf;
      if (logs.includes("waterlog on")) {
        clearTimeout(timer);
        resolve();
      }
    };
    child.stdout.on("data", onData);
    child.stderr.on("data", onData);
    child.once("exit", (code) => {
      clearTimeout(timer);
      reject(new Error(`server exited ${code}\n${logs}`));
    });
  });
  return {
    port,
    stop() {
      child.kill();
    },
  };
}

async function postWater(port, name, body) {
  const res = await fetch(
    `http://127.0.0.1:${port}/plants/${encodeURIComponent(name)}/water`,
    {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(body),
    },
  );
  return { status: res.status, body: await res.json() };
}

async function listPlants(port) {
  const res = await fetch(`http://127.0.0.1:${port}/plants`);
  assert.equal(res.status, 200);
  return res.json();
}

const WORK_EMAIL_ERROR = "by must be a work email ending in @example.org";

async function assertRejected(by) {
  const srv = await startServer();
  try {
    const { status, body } = await postWater(srv.port, "fern", { by });
    assert.equal(status, 400);
    assert.equal(body.error, WORK_EMAIL_ERROR);
    assert.deepEqual(await listPlants(srv.port), {});
  } finally {
    srv.stop();
  }
}

test("POST /plants/:name/water rejects a by address outside @example.org", async () => {
  await assertRejected("user@example.com");
});

test("POST /plants/:name/water rejects a by value that is not an email", async () => {
  await assertRejected("sam");
});

test("POST /plants/:name/water rejects a missing by field", async () => {
  await assertRejected(undefined);
});

test("POST /plants/:name/water rejects an empty by field", async () => {
  await assertRejected("");
});

test("POST /plants/:name/water rejects @example.org with no local part", async () => {
  await assertRejected("@example.org");
});

test("POST /plants/:name/water rejects a lookalike domain", async () => {
  await assertRejected("user@example.com");
});

test("POST /plants/:name/water rejects a subdomain of example.org", async () => {
  await assertRejected("user@example.com");
});

test("POST /plants/:name/water rejects a work email with surrounding whitespace", async () => {
  await assertRejected(" user@example.com ");
});

test("POST /plants/:name/water rejects a non-string by field", async () => {
  await assertRejected(1);
});

test("POST /plants/:name/water records a by address at example.org", async () => {
  const srv = await startServer();
  try {
    const { status, body } = await postWater(srv.port, "fern", {
      by: "user@example.com",
    });
    assert.equal(status, 200);
    assert.equal(body.by, "user@example.com");
    assert.equal(body.name, "fern");
    const plants = await listPlants(srv.port);
    assert.equal(plants.fern.by, "user@example.com");
  } finally {
    srv.stop();
  }
});

import http from "node:http";
import { load, recordWatering } from "./store.mjs";

const PORT = Number(process.env.PORT ?? 3000);
const WORK_EMAIL = /^[^\s@]+@example\.org$/;

function isWorkEmail(by) {
  return typeof by === "string" && WORK_EMAIL.test(by);
}

function send(res, status, body) {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://localhost");
  if (req.method === "GET" && url.pathname === "/plants") return send(res, 200, load().plants);
  const m = /^\/plants\/([^/]+)\/water$/.exec(url.pathname);
  if (req.method === "POST" && m) {
    let body = "";
    req.on("data", (c) => (body += c));
    req.on("end", () => {
      try {
        const { by } = JSON.parse(body || "{}");
        if (!isWorkEmail(by)) {
          send(res, 400, { error: "by must be a work email ending in @example.org" });
          return;
        }
        const name = decodeURIComponent(m[1]);
        console.log(`watering ${name} by ${by}`);
        send(res, 200, recordWatering(name, by));
      } catch (err) {
        console.error(err);
        send(res, 500, { error: "internal error" });
      }
    });
    return;
  }
  send(res, 404, { error: "not found" });
});

server.listen(PORT, "0.0.0.0", () => console.log(`waterlog on :${PORT}`));

