  recordWatering("fern", "user@example.com", new Date("2026-03-01T10:00:00Z"));
  assert.equal(load().plants.fern.by, "user@example.com");
});

test("two waterings in the same second are both kept", async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "waterlog-"));
  process.chdir(dir);
  const { recordWatering, load } = await import(
    "../src/store.mjs?same-second-" + Date.now() + "-" + Math.random()
  );
  recordWatering("fern", "user@example.com", new Date("2026-03-01T10:00:00.100Z"));
