  const fern = load().plants.fern;
  assert.deepEqual(
    fern.waterings.map((entry) => entry.by),
    ["user@example.com", "user@example.com"],
  );
  assert.equal(fern.by, "user@example.com");
  assert.equal(fern.lastWatered, "2026-03-01T10:00:00.900Z");
});

