tool_input.command:
node --input-type=module <<'EOF'
import { spawn } from "node:child_process";
import fs from "node:fs";
import net from "node:net";
import os from "node:os";
import path from "node:path";

const root = "<project>";
const dir = fs.mkdtempSync(path.join(os.tmpdir(), "waterlog-http-"));
const port = await new Promise((resolve, reject) => {
  const probe = net.createServer();
  probe.listen(0, "127.0.0.1", () => {
    const { port } = probe.address();
    probe.close((err) => (err ? reject(err) : resolve(port)));
  });
});
const child = spawn(process.execPath, [path.join(root, "src/server.mjs")], {
  cwd: dir,
  env: { ...process.env, PORT: String(port) },
  stdio: ["ignore", "pipe", "pipe"],
});
let logs = "";
await new Promise((resolve, reject) => {
  const timer = setTimeout(() => reject(new Error("start timeout\n" + logs)), 5000);
  const onData = (buf) => {
    logs += buf;
    if (logs.includes("waterlog on")) {
      clearTimeout(timer);
      resolve();
    }
  };
  child.stdout.on("data", onData);
  child.stderr.on("data", onData);
  child.once("exit", (code) => {
    clearTimeout(timer);
    reject(new Error("exited " + code + "\n" + logs));
  });
});

async function post(by) {
  const res = await fetch(`http://127.0.0.1:${port}/plants/fern/water`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ by }),
  });
  return { status: res.status, body: await res.json() };
}

const [a, b] = await Promise.all([
  post("user@example.com"),
  post("user@example.com"),
]);
const listed = await (await fetch(`http://127.0.0.1:${port}/plants`)).json();
const file = fs.readFileSync(path.join(dir, "data/waterings.json"), "utf8");
console.log(JSON.stringify({ a, b, listed, file }, null, 2));
child.kill();
EOF

