import type { Fired } from "./alerts/evaluate.js";
import { log } from "./lib/log.js";

/** Send the alert email through Postmark. The stand-in here logs it; the real sender lives in the deploy's secrets. */
export async function notify(f: Fired): Promise<void> {
  log.info({ alertId: f.alertId, stationId: f.stationId, heightMm: f.heightMm }, "alert fired");
}

import { evaluateAlerts } from "./alerts/evaluate.js";
import { config } from "./config.js";
import { type Db, type StationRow } from "./db.js";
import { newId } from "./lib/ids.js";
import { log } from "./lib/log.js";
import { notify } from "./notify.js";
import { fetchLatest } from "./upstream/noaa.js";

/** One poll: the newest reading of every station, stored when it is new, and the alerts it fires. */
export async function pollOnce(db: Db): Promise<number> {
  const stations = db.prepare("SELECT id, name, lat, lon FROM stations").all() as StationRow[];
  let stored = 0;
  for (const s of stations) {
    const latest = await fetchLatest(s.id);
    if (!latest) continue;
    const seen = db.prepare("SELECT 1 FROM readings WHERE station_id = ? AND at = ?").get(s.id, latest.at);
    if (seen) continue;
    db.prepare("INSERT INTO readings (id, station_id, height_mm, at) VALUES (?, ?, ?, ?)").run(newId(), s.id, latest.heightMm, latest.at);
    stored++;
    for (const f of evaluateAlerts(db, s.id, latest.heightMm)) await notify(f);
  }
  log.debug({ stored }, "poll done");
  return stored;
}

/** The poller loop, inside the API process (a cron job double-inserted readings when runs overlapped). */
export function startPoller(db: Db): NodeJS.Timeout {
  return setInterval(() => void pollOnce(db), config.pollIntervalMs);
}

import { type AlertRow, type Db } from "../db.js";

export interface Fired {
  alertId: string;
  stationId: string;
  thresholdMm: number;
  heightMm: number;
  email: string;
}

/**
 * An alert fires once when a reading crosses its threshold (armed → fired) and arms again only once the height has
 * fallen below the threshold. Returns the alerts that fired on this reading.
 */
export function evaluateAlerts(db: Db, stationId: string, heightMm: number): Fired[] {
  const alerts = db.prepare("SELECT * FROM alerts WHERE station_id = ?").all(stationId) as AlertRow[];
  const fired: Fired[] = [];
  for (const a of alerts) {
    if (a.armed === 1 && heightMm >= a.threshold_mm) {
      db.prepare("UPDATE alerts SET armed = 0 WHERE id = ?").run(a.id);
      fired.push({ alertId: a.id, stationId, thresholdMm: a.threshold_mm, heightMm, email: a.email });
    } else if (a.armed === 0 && heightMm < a.threshold_mm) {
      db.prepare("UPDATE alerts SET armed = 1 WHERE id = ?").run(a.id);
    }
  }
  return fired;
}

