import type { FastifyInstance } from "fastify";
import { toAlert, type AlertRow, type Db } from "../db.js";
import { ApiError } from "../errors.js";
import { newId } from "../lib/ids.js";

interface NewAlert {
  stationId: string;
  thresholdMm: number;
  email: string;
}

export function alertRoutes(app: FastifyInstance, db: Db) {
  app.post<{ Body: NewAlert }>("/v1/alerts", async (req, reply) => {
    const { stationId, thresholdMm, email } = req.body ?? ({} as NewAlert);
    if (!db.prepare("SELECT id FROM stations WHERE id = ?").get(stationId)) throw new ApiError("station_not_found");
    if (typeof email !== "string" || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) throw new ApiError("invalid_email");
    const row: AlertRow = { id: newId(), station_id: stationId, threshold_mm: Math.round(thresholdMm), email, armed: 1, created_at: new Date().toISOString() };
    db.prepare("INSERT INTO alerts (id, station_id, threshold_mm, email, armed, created_at) VALUES (?, ?, ?, ?, ?, ?)").run(row.id, row.station_id, row.threshold_mm, row.email, row.armed, row.created_at);
    reply.code(201);
    return toAlert(row);
  });

  app.get<{ Params: { id: string } }>("/v1/alerts/:id", async (req) => {
    const row = db.prepare("SELECT * FROM alerts WHERE id = ?").get(req.params.id) as AlertRow | undefined;
    if (!row) throw new ApiError("alert_not_found");
    return toAlert(row);
  });

  app.delete<{ Params: { id: string } }>("/v1/alerts/:id", async (req, reply) => {
    const r = db.prepare("DELETE FROM alerts WHERE id = ?").run(req.params.id);
    if (r.changes === 0) throw new ApiError("alert_not_found");
    reply.code(204);
    return null;
  });
}

import type { FastifyInstance } from "fastify";
import { toReading, toStation, type Db, type ReadingRow, type StationRow } from "../db.js";
import { ApiError } from "../errors.js";

const DEFAULT_LIMIT = 100;
const MAX_LIMIT = 500;

function pageOf(query: { limit?: string; offset?: string }) {
  const limit = query.limit === undefined ? DEFAULT_LIMIT : Number(query.limit);
  const offset = query.offset === undefined ? 0 : Number(query.offset);
  if (!Number.isInteger(limit) || limit < 1 || !Number.isInteger(offset) || offset < 0) throw new ApiError("limit_too_large", "limit and offset must be whole numbers");
  if (limit > MAX_LIMIT) throw new ApiError("limit_too_large", `limit is at most ${MAX_LIMIT}`);
  return { limit, offset };
}

export function stationRoutes(app: FastifyInstance, db: Db) {
  app.get<{ Querystring: { limit?: string; offset?: string } }>("/v1/stations", async (req) => {
    const { limit, offset } = pageOf(req.query);
    const rows = db.prepare("SELECT id, name, lat, lon FROM stations ORDER BY name LIMIT ? OFFSET ?").all(limit, offset) as StationRow[];
    return rows.map(toStation);
  });

  app.get<{ Params: { id: string } }>("/v1/stations/:id", async (req) => {
    if (!/^\d{7}$/.test(req.params.id)) throw new ApiError("invalid_station_id");
    const row = db.prepare("SELECT id, name, lat, lon FROM stations WHERE id = ?").get(req.params.id) as StationRow | undefined;
    if (!row) throw new ApiError("station_not_found");
    return toStation(row);
  });

  app.get<{ Params: { id: string }; Querystring: { since?: string; limit?: string } }>("/v1/stations/:id/readings", async (req) => {
    const station = db.prepare("SELECT id FROM stations WHERE id = ?").get(req.params.id);
    if (!station) throw new ApiError("station_not_found");
    const { limit } = pageOf({ limit: req.query.limit });
    const since = req.query.since ?? "1970-01-01T00:00:00.000Z";
    const rows = db.prepare("SELECT id, station_id, height_mm, at FROM readings WHERE station_id = ? AND at > ? ORDER BY at DESC LIMIT ?").all(req.params.id, since, limit) as ReadingRow[];
    return rows.map(toReading);
  });
}

/** Every error code the API answers with, and its status. `api/openapi.yaml` lists the same codes. */
export const ERROR_CODES = {
  station_not_found: 404,
  alert_not_found: 404,
  invalid_station_id: 400,
  invalid_email: 400,
  limit_too_large: 400,
} as const;

export type ErrorCode = keyof typeof ERROR_CODES;

/** Thrown by a route; the app's error handler turns it into `{ error: { code, message } }` with the code's status. */
export class ApiError extends Error {
  constructor(
    readonly code: ErrorCode,
    message?: string,
  ) {
    super(message ?? code.replace(/_/g, " "));
  }
  get status(): number {
    return ERROR_CODES[this.code];
  }
}

