import Fastify, { type FastifyInstance } from "fastify";
import { config } from "./config.js";
import { type Db } from "./db.js";
import { ApiError } from "./errors.js";
import { log } from "./lib/log.js";
import { alertRoutes } from "./routes/alerts.js";
import { stationRoutes } from "./routes/stations.js";

/**
 * The app, without listening: tests call it with app.inject.
 * `beforeRoutes` runs first. `onRoute` does not replay, so that is the only point a caller can see every route.
 */
export function buildApp(db: Db, beforeRoutes?: (app: FastifyInstance) => void) {
  const app = Fastify({ loggerInstance: log });
  app.addHook("onSend", async (_req, reply) => {
    reply.header("access-control-allow-origin", config.dashboardOrigin);
  });
  app.setErrorHandler((err, _req, reply) => {
    if (err instanceof ApiError) return reply.code(err.status).send({ error: { code: err.code, message: err.message } });
    log.error({ err }, "unhandled error");
    return reply.code(500).send({ error: { code: "internal", message: "something went wrong" } });
  });
  beforeRoutes?.(app);
  stationRoutes(app, db);
  alertRoutes(app, db);
  return app;
}

import pino from "pino";
import { config } from "../config.js";

/** The one logger. Structured fields first, the message second: `log.warn({ stationId, err }, "noaa fetch failed")`. */
export const log = pino({ level: config.logLevel });

import fs from "node:fs";
import { describe, expect, it } from "vitest";
import YAML from "yaml";
import { ERROR_CODES } from "../src/errors.js";
import { makeTestApp } from "./helpers.js";

const HTTP_METHODS = new Set(["get", "put", "post", "delete", "options", "head", "patch", "trace"]);

/** Every route the app registers is in api/openapi.yaml, and every error code is in its Error schema. */
describe("api/openapi.yaml", () => {
  const spec = YAML.parse(fs.readFileSync("api/openapi.yaml", "utf8"));
  const operations = new Set<string>();
  for (const [path, item] of Object.entries(spec.paths as Record<string, Record<string, unknown>>)) {
    const url = path.replace(/\{(\w+)\}/g, ":$1");
    for (const key of Object.keys(item)) {
      if (HTTP_METHODS.has(key)) operations.add(`${key.toUpperCase()} ${url}`);
    }
  }

  it("lists every route", async () => {
    const routes = new Set<string>();
    const { app } = makeTestApp((app) => {
      app.addHook("onRoute", (r) => {
        const methods = Array.isArray(r.method) ? r.method : [r.method];
        for (const method of methods) {
          // Fastify also registers a HEAD route for each GET. The contract is the route we wrote.
          if (method === "HEAD") continue;
          routes.add(`${method} ${r.url}`);
        }
      });
    });
    await app.ready();
    expect(routes.size).toBeGreaterThan(0);
    for (const route of routes) expect(operations, route).toContain(route);
  });

  it("lists every error code", () => {
    const codes: string[] = spec.components.schemas.Error.properties.error.properties.code.enum;
    for (const c of Object.keys(ERROR_CODES)) expect(codes).toContain(c);
  });
});

